const mapaProductos = {};

function reconstruirMapaProductos() {
  Object.keys(mapaProductos).forEach(k => delete mapaProductos[k]);

  Object.keys(productos).forEach(cat => {
    productos[cat].forEach(item => {
      if (!item.eliminado) {
        item.categoria = cat;
        mapaProductos[item.id] = item;
      }
    });
  });

  Object.keys(productosDinamicosTiendas).forEach(tId => {
    const prods = productosDinamicosTiendas[tId];
    if (prods && typeof prods === 'object') {
      Object.keys(prods).forEach(pKey => {
        const p = prods[pKey];
        if (p && !p.eliminado) {
          p.id = pKey;
          p.tiendaId = tId;
          mapaProductos[pKey] = p;
        } else if (p && p.eliminado) {
          delete mapaProductos[pKey];
        }
      });
    }
  });
}

function normalizarTexto(txt) {
  return (txt || '').normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
}

reconstruirMapaProductos();
